#!/usr/bin/env bash
# Materialise the corpus into $NAV_CORPUS_DIR (outside the repository).
#   NAV_CORPUS_DIR=<dir> fetch.sh <nav_oracle binary>
#   NAV_CORPUS_DIR=<dir> fetch.sh --public-only
# `--public-only` downloads only the pinned third-party meshes and skips the procedural
# ones, which need the oracle's `gen` command; the cross-platform determinism check
# (reference/determinism.sh) uses only the downloaded meshes.
# Upstream meshes are downloaded at the pinned commit and checked against the
# SHA-256 in MANIFEST.toml; procedural meshes are generated by the oracle and
# checked the same way, so a generator change shows up as a hash mismatch.
# Case files name meshes relative to the same directory.
set -euo pipefail

oracle=${1:?usage: NAV_CORPUS_DIR=<dir> fetch.sh <nav_oracle binary> | --public-only}
here=$(cd "$(dirname "$0")" && pwd)
data=${NAV_CORPUS_DIR:?set NAV_CORPUS_DIR to the directory that will hold the corpus}
mkdir -p "$data"

commit=9f4ce64458dfae86e1239c525ddc219c4e9e06f1
base="https://raw.githubusercontent.com/recastnavigation/recastnavigation/$commit/RecastDemo/Bin/Meshes"

check() { # file expected-sha256
  local got
  got=$(sha256sum "$1" | cut -d' ' -f1)
  if [ "$got" != "$2" ]; then
    echo "hash mismatch: $1 ($got, expected $2)" >&2
    exit 1
  fi
}

fetch() { # name sha256
  if [ ! -f "$data/$1" ]; then
    curl -fsSL "$base/$1" -o "$data/$1.part"
    mv "$data/$1.part" "$data/$1"
  fi
  check "$data/$1" "$2"
}

gen() { # kind sha256
  "$oracle" gen "$1" "$data/gen_$1.obj"
  check "$data/gen_$1.obj" "$2"
}

fetch dungeon.obj    6b157db01f8eaa4b0290d18bd8d6515e969f674213de6f3a3e014f82ae1facc4
fetch nav_test.obj   ed27fc1a85ef73faa4d0621d640b67842e9081606e732267c662327c35fabc0f
fetch undulating.obj 3207fee6720faa45f9a677e2a64e1be516318efee94cb0c7ef15a55c288fa2ff

# Godot demo projects (MIT), 3D navigation demo level, pinned commit.
godot=b761b4cd5718a7118f2c95eb55f181d0a5f004f1
if [ ! -f "$data/godot_nav_level.obj" ]; then
  curl -fsSL "https://raw.githubusercontent.com/godotengine/godot-demo-projects/$godot/3d/navigation/models/level_mesh/level_mesh.obj" \
    -o "$data/godot_nav_level.obj.part"
  mv "$data/godot_nav_level.obj.part" "$data/godot_nav_level.obj"
fi
check "$data/godot_nav_level.obj" b79ff8b1a2c5880ec2094ee42cd4834db75af755f6f0d4dad7a6ed3318f9b174

if [ "$oracle" != "--public-only" ]; then
  while read -r kind sha; do
    gen "$kind" "$sha"
  done < "$here/generated.sha256"
fi

echo "corpus ready in $data"
